package org.sleepwell.app;

import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import androidx.test.ext.junit.runners.AndroidJUnit4;import androidx.test.platform.app.InstrumentationRegistry;import org.junit.*;import org.junit.runner.RunWith;import java.util.*;import java.util.concurrent.atomic.*;import static org.junit.Assert.*;

/** Shared native challenge controls, UUID private preferences, fake sensor; no AlarmActivity/output. */
@RunWith(AndroidJUnit4.class)
public final class ChallengePackNativeTest {
    Context c;SharedPreferences prefs;String name;TiltSensors.Factory prior;TiltMazeTask task;FakeSensor sensor;AtomicBoolean current;AtomicInteger completed,fallback;
    static final class FakeSensor implements TiltSensors.Port {TiltSensors.Listener listener,old;long now=1_000_000_000L;boolean available=true,stop=true;int starts,stops,rotation;public boolean start(TiltSensors.Listener listener){starts++;this.listener=listener;old=listener;return available;}public boolean stop(){stops++;if(stop)listener=null;return stop;}public long now(){return now;}public int rotation(){return rotation;}void sample(double x,double y){now+=50_000_000L;if(listener!=null)listener.sample(now,x,y,9.8);}void calibrate(){for(int n=0;n<16;n++)sample(0,0);}}
    @Before public void setup(){c=InstrumentationRegistry.getInstrumentation().getTargetContext();name="challenge-pack-"+UUID.randomUUID();prefs=c.getSharedPreferences(name,0);prior=TiltSensors.factory;sensor=new FakeSensor();TiltSensors.factory=context->sensor;current=new AtomicBoolean(true);completed=new AtomicInteger();fallback=new AtomicInteger();}
    @After public void cleanup(){main(()->{if(task!=null)task.close();});TiltSensors.factory=prior;c.deleteSharedPreferences(name);}
    void main(Runnable action){InstrumentationRegistry.getInstrumentation().runOnMainSync(action);}
    LinearLayout card(){return new LinearLayout(c);}
    static Button button(View view,String label){if(view instanceof Button b&&label.contentEquals(b.getText()))return b;if(view instanceof ViewGroup group)for(int n=0;n<group.getChildCount();n++){Button result=button(group.getChildAt(n),label);if(result!=null)return result;}return null;}
    static EditText input(View view){if(view instanceof EditText e)return e;if(view instanceof ViewGroup group)for(int n=0;n<group.getChildCount();n++){EditText result=input(group.getChildAt(n));if(result!=null)return result;}return null;}
    @Test public void persistedMazePositionAndFallbackReopenForExactUnitOnly(){TiltMaze maze=ChallengePackState.maze(prefs,"run",2,1);maze.move(.1,0);String key=ChallengePackState.key("run",2,1);assertTrue(ChallengePackState.save(prefs,key,maze));TiltMaze reopened=ChallengePackState.maze(prefs,"run",2,1);assertEquals(maze.x,reopened.x,0);assertEquals(maze.y,reopened.y,0);assertTrue(ChallengePackState.chooseFallback(prefs,key));assertTrue(ChallengePackState.fallback(prefs,"run",2,1));TiltMaze successor=ChallengePackState.maze(prefs,"run",3,0);assertFalse(ChallengePackState.fallback(prefs,"run",3,0));assertFalse(ChallengePackState.save(prefs,key,maze));assertFalse(ChallengePackState.chooseFallback(prefs,key));assertEquals(1.5,successor.x,0);}
    @Test public void corruptPositionIsAnErrorAndCannotSilentlyResetProgress(){ChallengePackState.maze(prefs,"run",0,0);assertTrue(prefs.edit().putLong("tiltX",Double.doubleToLongBits(Double.NaN)).commit());Map<String,?> before=new HashMap<>(prefs.getAll());assertThrows(IllegalArgumentException.class,()->ChallengePackState.maze(prefs,"run",0,0));assertEquals(before,prefs.getAll());}
    @Test public void newTasksRoundTripThroughAlarmRoutineAndCompletedUnitCheckpoint()throws Exception{ChallengeRoutine routine=new ChallengeRoutine(List.of(new ChallengeRoutine.Task("Counting",2),new ChallengeRoutine.Task("Tilt maze",1),new ChallengeRoutine.Task("Flags",2)));Alarm alarm=new Alarm(7);alarm.setRoutine(routine);Alarm reopened=Alarm.read(alarm.json());assertEquals(5,reopened.challenges().units());int next=reopened.challenges().advance(2,2);assertTrue(prefs.edit().putString("alarm",reopened.json().toString()).putInt("completed",next).commit());Alarm finalAlarm=Alarm.read(new org.json.JSONObject(prefs.getString("alarm","")));assertEquals("Flags",finalAlarm.challenges().at(prefs.getInt("completed",0)).task.type);assertEquals(3,finalAlarm.challenges().advance(3,2));}
    @Test public void sharedCountingControlRejectsWrongAndStaleResponsesThenAcceptsCorrect(){main(()->{LinearLayout card=card();CountingPuzzle puzzle=CountingPuzzle.create("run",0,0);EditText answer=WakePuzzleView.counting(card,"run",0,0,null,current::get,completed::incrementAndGet);answer.setText(""+(puzzle.answer()+1));button(card,"Check count").performClick();assertEquals(0,completed.get());current.set(false);answer.setText(""+puzzle.answer());button(card,"Check count").performClick();assertEquals(0,completed.get());current.set(true);button(card,"Check count").performClick();assertEquals(1,completed.get());});}
    @Test public void sharedFlagsControlUsesActualDrawnQuestionAndOnlyCorrectChoiceCompletes(){main(()->{LinearLayout card=card();FlagPuzzle puzzle=FlagPuzzle.create("run",0,0);WakePuzzleView.flags(card,"run",0,0,current::get,completed::incrementAndGet);int wrong=puzzle.choices.stream().filter(n->n!=puzzle.target).findFirst().orElseThrow();button(card,FlagPuzzle.COUNTRIES.get(wrong)).performClick();assertEquals(0,completed.get());current.set(false);button(card,FlagPuzzle.COUNTRIES.get(puzzle.target)).performClick();assertEquals(0,completed.get());current.set(true);button(card,FlagPuzzle.COUNTRIES.get(puzzle.target)).performClick();assertEquals(1,completed.get());});}
    @Test public void fakeTiltRequiresCalibrationFreshPathAndStopsBeforeCompleting(){main(()->{task=new TiltMazeTask(card(),prefs,"run",0,0,current::get,()->{assertNull(sensor.listener);completed.incrementAndGet();},fallback::incrementAndGet);assertEquals(0,sensor.starts);task.calibrate();assertEquals(1,sensor.starts);long armed=sensor.now;sensor.old.sample(armed-1,-3,0,9.8);assertEquals(1.5,task.maze.x,0);assertEquals(0,completed.get());sensor.calibrate();assertTrue(task.motion.calibrated());for(int[] point:path(task.maze)){double targetX=point[0]+.5,targetY=point[1]+.5;int count=0;while(Math.hypot(task.maze.x-targetX,task.maze.y-targetY)>.10&&completed.get()==0&&count++<250){double dx=targetX-task.maze.x,dy=targetY-task.maze.y;sensor.sample(Math.abs(dx)>.04?-Math.signum(dx)*2:0,Math.abs(dy)>.04?Math.signum(dy)*2:0);}assertTrue("Could not follow generated corridor",count<250);}assertEquals(1,completed.get());assertTrue(task.released());TiltSensors.Listener stale=sensor.old;stale.sample(sensor.now+50_000_000L,0,0,9.8);assertEquals(1,completed.get());TiltMaze reopened=ChallengePackState.maze(prefs,"run",0,0);assertTrue(reopened.solved());});}
    @Test public void pauseStopsFakeSensorAndRequiresNewCalibrationWithoutChangingMaze(){main(()->{task=new TiltMazeTask(card(),prefs,"run",0,0,current::get,completed::incrementAndGet,fallback::incrementAndGet);task.calibrate();sensor.calibrate();sensor.sample(-2,0);double x=task.maze.x,y=task.maze.y;TiltSensors.Listener stale=sensor.old;task.close();stale.sample(sensor.now+50_000_000L,-3,0,9.8);assertEquals(x,task.maze.x,0);assertEquals(y,task.maze.y,0);assertTrue(task.released());task=new TiltMazeTask(card(),prefs,"run",0,0,current::get,completed::incrementAndGet,fallback::incrementAndGet);assertEquals(x,task.maze.x,0);assertEquals(y,task.maze.y,0);assertEquals(1,sensor.starts);task.calibrate();assertFalse(task.motion.calibrated());assertEquals(0,completed.get());});}
    @Test public void unsupportedSensorAndFailedCleanupCannotGrantCompletionOrSilentlyFallback(){main(()->{sensor.available=false;LinearLayout card=card();task=new TiltMazeTask(card,prefs,"run",0,0,current::get,completed::incrementAndGet,fallback::incrementAndGet);task.calibrate();assertTrue(task.failed);assertEquals(0,completed.get());sensor.stop=false;button(card,"Use Math instead").performClick();assertEquals(0,fallback.get());sensor.stop=true;button(card,"Use Math instead").performClick();assertEquals(1,fallback.get());assertTrue(ChallengePackState.fallback(prefs,"run",0,0));assertEquals(0,completed.get());});}
    static List<int[]> path(TiltMaze maze){List<int[]> queue=new ArrayList<>();queue.add(new int[]{1,1});Map<Integer,Integer> parent=new HashMap<>();int start=maze.size+1;parent.put(start,-1);int goal=(maze.size-2)*maze.size+maze.size-2;for(int n=0;n<queue.size();n++){int[] p=queue.get(n);int key=p[1]*maze.size+p[0];if(key==goal)break;for(int[] d:new int[][]{{1,0},{-1,0},{0,1},{0,-1}}){int x=p[0]+d[0],y=p[1]+d[1],next=y*maze.size+x;if(maze.open(x,y)&&!parent.containsKey(next)){parent.put(next,key);queue.add(new int[]{x,y});}}}List<int[]> path=new ArrayList<>();for(int key=goal;key!=-1;key=parent.get(key))path.add(new int[]{key%maze.size,key/maze.size});Collections.reverse(path);return path;}
}
